"""Fixed execution tools and real-browser observations for repository-level repair."""

import json
from copy import deepcopy
from hashlib import sha256
import os
from pathlib import Path
import re
import shutil
import subprocess
from tempfile import TemporaryDirectory
from time import monotonic, sleep
from urllib.request import urlopen

from infrastructure.shared.project.dependencies import install_dependencies
from infrastructure.repository.execution.backend import BackendChecks, require_green as backend_green
from infrastructure.repository.execution.harness import prepare_e2e
from infrastructure.repository.execution.e2e import E2EChecks
from infrastructure.repository.execution.browser import require_green
from infrastructure.utils.files import save_json, save_text
from infrastructure.repository.workspace import HARNESS
from infrastructure.utils.processes import start_process, stop_process


PROBE = "frontend/tests/e2e/support/repository-inspect.spec.ts"


def prepare_harness(output):
    prepare_e2e(output)
    package = output / "package.json"
    manifest = json.loads(package.read_text(encoding="utf-8-sig"))
    manifest.setdefault("devDependencies", {})["@playwright/test"] = "1.64.1"
    save_json(package, manifest)


class Checks:
    def __init__(self, repository, *, timeout=300):
        self.repository = repository
        self.output = repository.output
        self.timeout = timeout
        self.installed = False
        self.browser_ready = False
        self.number = 0
        self.cache = {}
        self.stats = {"executed_checks": 0, "cache_hits": 0}
        self.verified_sources = self.source_versions()

    def source_versions(self):
        return {path: sha256(self.repository.path(path).read_bytes()).hexdigest()
            for path in self.repository.paths() if not path.endswith((".test.ts", ".spec.ts"))}

    def fingerprint(self, name, suites, *, artifacts=True):
        paths = self.repository.paths()
        base = {path for path in paths if "/tests/" not in path}
        if name in {"backend", "backend_typecheck"}:
            base = {path for path in base if not path.startswith("frontend/")}
            selected = suites["backend"]
            helpers = {path for path in paths if path.startswith("backend/tests/") and not path.endswith(".test.ts")}
        elif name in {"frontend_typecheck", "e2e"}:
            selected = suites["e2e"]
            helpers = {path for path in paths if "/tests/" in path and not path.endswith((".test.ts", ".spec.ts"))}
        else:
            selected, helpers = [], set()
            # Nonstandard build configs can include tests. In that case their content
            # participates in the build key instead of assuming src-only compilation.
            for config in ("frontend/tsconfig.json", "backend/tsconfig.json"):
                try:
                    value = json.loads(self.repository.path(config).read_text(encoding="utf-8-sig"))
                    if not isinstance(value, dict):
                        raise ValueError("Invalid TypeScript config")
                except (ValueError, OSError):
                    value = {}
                includes = value.get("include") or []
                includes = includes if isinstance(includes, list) else []
                if value.get("extends") or not includes or any(not str(item).startswith(("src", "vite.config")) for item in includes):
                    helpers.update(path for path in paths if "/tests/" in path)
        # Include imported test files as well as helpers. Unknown dynamic test imports
        # conservatively bind all tests to this result.
        queue = list(set(selected) | base)
        seen = set(queue)
        while queue:
            path = queue.pop()
            source = self.repository.path(path).read_text(encoding="utf-8-sig")
            if re.search(r"\b(?:import|require)\s*\(", source):
                helpers.update(item for item in paths if "/tests/" in item)
            import posixpath
            for relative in re.findall(r'from\s*[\'\"](\.[^\'\"]+)[\'\"]|import\s*[\'\"](\.[^\'\"]+)[\'\"]', source):
                base_path = posixpath.normpath(posixpath.join(posixpath.dirname(path), next(part for part in relative if part)))
                candidates = [base_path, base_path + ".ts", base_path + ".tsx", base_path + "/index.ts"]
                if base_path.endswith(".js"):
                    candidates.extend([base_path[:-3] + ".ts", base_path[:-3] + ".tsx"])
                found = next((item for item in candidates if item in paths), None)
                if found and found not in seen:
                    seen.add(found)
                    queue.append(found)
        hashes = {path: sha256(self.repository.path(path).read_bytes()).hexdigest() for path in sorted(base | helpers | seen)}
        for package in ("@playwright/test", "typescript", "tsx", "better-sqlite3"):
            path = self.output / "node_modules" / package / "package.json"
            hashes[f"installed:{package}"] = sha256(path.read_bytes()).hexdigest() if path.is_file() else None
        if artifacts and name in {"build", "production_smoke"}:
            for folder in ("frontend/dist", "backend/dist"):
                for path in (self.output / folder).rglob("*"):
                    if path.is_file() and not path.is_symlink():
                        hashes[path.relative_to(self.output).as_posix()] = sha256(path.read_bytes()).hexdigest()
        runtime = {key: value for key, value in os.environ.items() if key.startswith("ARC_") or key in {"TZ", "NODE_ENV", "NODE_OPTIONS", "LANG"}}
        node = shutil.which("node")
        runtime["node"] = node
        runtime["node_mtime"] = Path(node).stat().st_mtime_ns if node else None
        return sha256(json.dumps({"name": name, "files": hashes, "runtime": runtime}, sort_keys=True).encode()).hexdigest()

    def verify(self, files, accepted):
        current = self.source_versions()
        changed = {path for path in current.keys() | self.verified_sources.keys() if current.get(path) != self.verified_sources.get(path)}
        shared = any(path in HARNESS or not path.startswith(("frontend/src/pages/", "frontend/src/components/", "backend/src/api/"))
            or path == "backend/src/api/register.ts" for path in changed)
        if shared:
            result = self.run("all")
            result["selection_reason"] = "Shared/config/schema/unknown dependency changed; full regression fallback"
        else:
            regression = {path for item in accepted.values() for path in item["tests"]} if changed else set()
            result = self.run("feature", e2e_files=sorted(set(files) | regression))
            result["selection_reason"] = "Current specs plus all accepted regressions for source changes; cached unaffected checks"
        if result["status"] == "GREEN":
            self.verified_sources = self.source_versions()
        save_json(self.output / ".arc/repository_checks.json", result)
        return result

    def prepare(self, browser=False):
        prepare_harness(self.output)
        if not self.installed:
            self.cache.clear()
            install_dependencies(self.output)
            self.installed = True
        if browser and not self.browser_ready:
            E2EChecks(self.output).install_browser()
            self.browser_ready = True

    def suites(self):
        return {
            "backend": [path for path in self.repository.paths() if path.startswith("backend/tests/") and path.endswith(".test.ts")],
            "e2e": [path for path in self.repository.paths() if path.startswith("frontend/tests/e2e/")
                and path.endswith(".spec.ts") and "/support/" not in path],
        }

    def run(self, kind="all", *, report_name="repository_checks.json", e2e_files=None, force=False) -> dict:
        if kind not in {"all", "feature", "typecheck", "backend", "e2e", "build", "smoke"}:
            raise ValueError("check kind must be all, typecheck, backend, e2e, build, or smoke")
        self.prepare(browser=kind in {"all", "feature", "e2e"})
        frontend = E2EChecks(self.output)
        backend = BackendChecks(self.output, timeout=self.timeout)
        frontend.timeout = self.timeout
        suites = self.suites()
        if e2e_files is not None:
            if not isinstance(e2e_files, list) or not e2e_files or not set(e2e_files) <= set(suites["e2e"]):
                raise ValueError("Select existing browser spec paths")
            suites["e2e"] = sorted(set(e2e_files))
        results = {}

        def run_check(name, action, validator=None):
            result = None
            fingerprint = self.fingerprint(name, suites)
            if not force and fingerprint in self.cache:
                results[name] = {**deepcopy(self.cache[fingerprint]), "cached": True, "executed": False, "elapsed_seconds": 0}
                self.stats["cache_hits"] += 1
                print(f"Repository check | {name} | GREEN (cached)", flush=True)
                return
            started = monotonic()
            self.stats["executed_checks"] += 1
            input_fingerprint = self.fingerprint(name, suites, artifacts=False)
            try:
                result = action()
                if result["returncode"]:
                    raise ValueError(result.get("output", f"{name} failed"))
