from hashlib import sha256


class WorkMemory:
    def __init__(self, repository):
        self.repository = repository
        self.active = None
        self.features = {}
        self.first_check_turn = None
        self.final_review = self._entry("Verify accepted workflows and finish")

    @staticmethod
    def _entry(goal=""):
        return {"goal": goal, "hypothesis": "", "next_step": "", "blocker": "",
            "facts": [], "evidence": [], "changed_paths": [], "last_failure": None}

    def select(self, requirements, accepted):
        if self.active is None or self.active in accepted:
            self.active = next((key for key in requirements if key not in accepted), None)
        if self.active:
            self.features.setdefault(self.active, self._entry())
        return self.active

    def update(self, update, requirements, accepted):
        if not isinstance(update, dict) or not update or set(update) - {"feature", "goal", "hypothesis", "next_step", "blocker", "facts"}:
            raise ValueError("work requires feature/goal/hypothesis/next_step/blocker/facts fields")
        identity = update.get("feature", self.active)
        final = identity is None and requirements.keys() == accepted.keys()
        if not final and (identity not in requirements or identity in accepted):
            raise ValueError("Choose a known, unaccepted scenario as the current feature")
        fields = {}
        for field in ("goal", "hypothesis", "next_step", "blocker"):
            if field in update:
                if not isinstance(update[field], str) or len(update[field]) > 1000:
                    raise ValueError(f"work.{field} must be text under 1000 characters")
                fields[field] = update[field]
        facts = update.get("facts", [])
        if not isinstance(facts, list) or len(facts) > 6:
            raise ValueError("Supply up to six source-linked working facts per update")
        prepared = []
        for fact in facts:
            if not isinstance(fact, dict) or not isinstance(fact.get("text"), str) or not 1 <= len(fact["text"]) <= 600:
                raise ValueError("Each working fact needs text under 600 characters")
            files = fact.get("files")
            supplied = files if isinstance(files, dict) else {}
            if isinstance(files, dict):
                files = list(files)
            if not isinstance(files, list) or not 1 <= len(files) <= 8:
                raise ValueError("Each working fact needs 1 to 8 inspected source paths")
            hashes = {}
            for path in files:
                target = self.repository.path(path)
                checksum = sha256(target.read_bytes()).hexdigest() if target.is_file() else None
                if checksum is None or self.repository.observed.get(path) != checksum:
                    raise ValueError(f"Read or search the current source before recording a fact: {path}")
                if path in supplied and supplied[path] != checksum:
                    raise ValueError(f"Working fact refers to a stale source hash: {path}")
                hashes[path] = checksum
            prepared.append({"text": fact["text"], "files": hashes, "revision": self.repository.revision})
        self.active = identity
        self.select(requirements, accepted)
        entry = self.final_review if final else self.features[identity]
        entry.update(fields)
        for fact in prepared:
            entry["facts"] = [old for old in entry["facts"] if old["text"] != fact["text"]]
            entry["facts"].append(fact)
        entry["facts"] = entry["facts"][-12:]

    def invalidate(self):
        for entry in [*self.features.values(), self.final_review]:
            for fact in entry["facts"]:
                fact["needs_recheck"] = True

    def record(self, action, observation, turn):
        entry = self.features[self.active] if self.active else self.final_review
        name = action.get("action") if isinstance(action, dict) else None
        name = name if isinstance(name, str) else None
        status = observation.get("status") if isinstance(observation, dict) else None
        checks = observation.get("checks", {}) if isinstance(observation, dict) else {}
        if isinstance(checks.get("checks"), dict):
            checks = checks["checks"]  # Successful accept/finish wraps the execution report.
        if name in {"check", "accept", "finish"} and checks:
            if self.first_check_turn is None:
                self.first_check_turn = turn
            event = {"turn": turn, "action": name, "revision": self.repository.revision,
                "status": status, "checks": {key: item.get("status") for key, item in checks.items()}}
            entry["evidence"].append(event)
            entry["evidence"] = entry["evidence"][-6:]
        if name in {"edit", "replace"} and observation.get("changed"):
            entry["changed_paths"] = sorted(set(entry["changed_paths"]) | set(observation["changed"]))[-30:]
        if status in {"FAILED", "TOOL_ERROR", "INCOMPLETE", "CONTRACT_INCOMPLETE"}:
            failed = {key: item.get("error", item.get("result", {})) for key, item in checks.items() if item.get("status") != "GREEN"}
            diagnostics = []
            for item in checks.values():
                result = item.get("result") if isinstance(item, dict) else None
                if isinstance(result, dict):
                    diagnostics.extend(result.get("failure_details") or [])
            entry["last_failure"] = {"turn": turn, "action": name, "revision": self.repository.revision,
                "status": status,
                "error": str(observation.get("error") or failed or observation.get("remaining", ""))[:2000],
                "diagnostics": diagnostics[:3]}

    def snapshot(self, identity=None):
        identity = self.active if identity is None else identity
        if identity is not None and identity not in self.features:
            return None
        entry = self.final_review if identity is None else self.features[identity]
        facts = []
        for fact in entry["facts"]:
            stale = bool(fact.get("needs_recheck"))
            for path, checksum in fact["files"].items():
                target = self.repository.path(path)
                stale |= not target.is_file() or sha256(target.read_bytes()).hexdigest() != checksum
            facts.append({**fact, "status": "stale" if stale else "source_current", "model_authored": True})
        return {"feature": identity, **entry, "facts": facts}

    def progress(self, requirements, accepted, checks):
        identity = self.select(requirements, accepted)
        paths = self.repository.paths()
        backend = [path for path in paths if path.startswith("backend/tests/") and path.endswith(".test.ts")]
        e2e = [path for path in paths if path.startswith("frontend/tests/e2e/") and path.endswith(".spec.ts") and "/support/" not in path]
        accepted_specs = {path for item in accepted.values() for path in item.get("tests", [])}
        unaccepted_specs = [path for path in e2e if path not in accepted_specs]
        current = checks is not None and checks.get("revision") == self.repository.revision
