        if identity:
            gaps.append("Current scenario is not accepted. Map its own spec and accept after checks pass; other scenario coverage remains unverified.")
        return {"current_feature": identity, "requirement": requirements.get(identity),
            "accepted_count": len(accepted), "required_count": len(requirements),
            "global_test_inventory": {"backend_count": len(backend), "e2e_count": len(e2e),
