                if (self.report["status"] != "GREEN"
                        and self.report.get("stop_reason") not in {"PARTIAL_SUBMISSION", "MODEL_UNAVAILABLE"}):
                    self.report["status"] = "COMPLETED_WITH_FAILURES"
                    self.report["stop_reason"] = "BUDGET_EXHAUSTED"
            except BaseException as error:
                self.report["status"] = "INTERRUPTED" if isinstance(error, KeyboardInterrupt) else "FAILED"
                self.report["error"] = str(error)
                raise
            finally:
                self.report["duration_seconds"] = round(time.monotonic() - started, 3)
                self.save()
        return self.output

    def save_candidate(self, *, ready):
        entry = {"revision": self.repository.revision, "ready": ready, "accepted_count": len(self.accepted),
            "checks": self.report.get("checks"), "delivery": self.report.get("delivery") if ready else None,
            "verification_status": self.report["status"]}
        identity = self.repository.candidate(self.accepted, entry)
        self.report["candidates"].append({"id": identity, **{key: value for key, value in entry.items() if key not in {"checks", "delivery"}}})
        return identity

    def prepare_delivery(self, *, allow_fallback=True):
        """Separate internal acceptance from delivering a runnable app to the external evaluator."""
        self.delivery_attempted = True
        delivery = {"status": "FAILED", "verification_status": self.report["status"],
            "revision": self.repository.revision, "checks": {}, "process_exit_code": 1}
        try:
            if self.report["status"] not in {"GREEN", "COMPLETED_WITH_FAILURES"}:
                raise ValueError("Compilation did not reach a normal terminal state")
            required = ("deploy.sh", "package.json", "frontend/package.json", "backend/package.json",
                "backend/src/server.ts")
            missing = [path for path in required if not self.repository.path(path).is_file()]
            if missing:
                raise ValueError(f"Missing delivery files: {', '.join(missing)}")
            previous = self.report.get("checks") or {}
            required_checks = {"build", "production_smoke"}
            # finish just verified this exact revision. Incomplete runs need a fresh
            # production-only check that does not depend on model-authored test suites.
            if (self.report["status"] == "GREEN" and previous.get("revision") == self.repository.revision
                    and previous.get("status") == "GREEN"
                    and all(previous.get("checks", {}).get(name, {}).get("status") == "GREEN" for name in required_checks)):
                result = {"status": "GREEN", "revision": self.repository.revision,
                    "checks": {name: previous["checks"][name] for name in sorted(required_checks)}}
            else:
                result = self.checks.run("smoke", report_name="delivery_checks.json")
            delivery["checks"] = result.get("checks", {})
            if (result.get("status") != "GREEN" or result.get("revision") != self.repository.revision
                    or any(delivery["checks"].get(name, {}).get("status") != "GREEN" for name in required_checks)):
                raise ValueError("Final application build/startup verification failed")
            delivery.update(status="READY", process_exit_code=0)
        except Exception as error:
            delivery["error"] = str(error)[-12_000:]
        if delivery["status"] == "FAILED" and allow_fallback and self.report["status"] == "COMPLETED_WITH_FAILURES":
            candidates = sorted((item for item in self.report.get("candidates", []) if item["ready"]),
                key=lambda item: (item["accepted_count"], item["id"]), reverse=True)
            original = self.repository.candidate(self.accepted, {"reason": "Before delivery fallback"})
            old_checks = self.report.get("checks")
            self.report["delivery_recovery"] = {"rejected_candidate": original,
                "checks": old_checks, "delivery": delivery}
            fallback_candidates = list(candidates)
            if self.baseline and all(item["id"] != self.baseline for item in fallback_candidates):
                fallback_candidates.append({"id": self.baseline, "accepted_count": -1, "baseline": True})
            for candidate in fallback_candidates:
                self.accepted = self.repository.restore(candidate["id"], candidate=True)
                self.work.invalidate()
                self.checks.installed = False
                self.report["checks"] = None
                attempt = self.prepare_delivery(allow_fallback=False)
                if attempt["status"] == "READY":
                    attempt["restored_candidate"] = candidate["id"]
                    attempt["latest_candidate_error"] = delivery["error"]
                    attempt["baseline_fallback"] = bool(candidate.get("baseline"))
                    self.report["delivery"] = attempt
                    save_json(self.arc_dir / "delivery_checks.json", attempt)
                    self.save()
                    return attempt
            self.accepted = self.repository.restore(original, candidate=True)
            self.work.invalidate()
            self.report["checks"] = old_checks
            self.checks.installed = False
        # Keep the original acceptance status, suites and failure evidence intact.
        self.report["delivery"] = delivery
        save_json(self.arc_dir / "delivery_checks.json", delivery)
        self.save()
        return delivery

    def act(self, request):
        if not isinstance(request, dict):
            raise ValueError("Return one action object")
        warning = None
        if "work" in request:
            try:
                self.work.update(request["work"], self.requirements["features"], self.accepted)
            except (ValueError, KeyError, TypeError, OSError) as error:
                if request.get("action") == "remember":
                    raise
                warning = f"Working memory was not updated: {error}"
        result = self._act(request)
        if warning:
            result.setdefault("warnings", []).append(warning)
        return result

    def _act(self, request):
        action = request.get("action")
        if action == "history":
            turn, offset, limit = request["turn"], request.get("offset", 0), request.get("limit", 12000)
            if any(type(value) is not int for value in (turn, offset, limit)) or turn < 1 or offset < 0 or not 1 <= limit <= 20000:
                raise ValueError("history requires a positive turn, nonnegative offset and limit <= 20000")
            for line in (self.arc_dir / "repository_events.jsonl").read_text().splitlines():
                if json.loads(line)["turn"] == turn:
                    return {"turn": turn, "offset": offset, "content": line[offset:offset + limit],
                        "total_characters": len(line), "next_offset": offset + limit if offset + limit < len(line) else None}
            raise ValueError("No completed event for that turn")
        if action == "contract":
            audit = audit_contract(self.repository, self.contract)
            audit["ui_warnings"] = repository_ui_warnings(self.repository)
            audit["test_coverage"] = contract_test_gaps(self.contract,
                list(self.contract.get("features", {})), self.checks.suites()["e2e"], self.repository)
            save_json(self.arc_dir / "contract_audit.json", audit)
            return audit
        if action == "submit" or action == "finish" and request.get("partial") is True:
            if not self.accepted and not self.report.get("checks"):
                return {"status": "TOOL_ERROR",
                    "error": "Run at least one check or accept a realistic workflow before partial submission; "
                        "an unverified scaffold is not a deliverable attempt.",
                    "remaining_turns": self.max_turns - self.report.get("turns", 0)}
            previous = self.report["status"]
            self.report["status"] = "COMPLETED_WITH_FAILURES"
            delivery = self.prepare_delivery()
            if delivery["status"] == "READY":
                self.report["stop_reason"] = "PARTIAL_SUBMISSION"
                self.report["submission_reason"] = str(request.get("reason", "Model requested partial delivery"))[:1000]
                self.save_candidate(ready=True)
                return {"status": "SUBMITTED", "delivery": delivery, "remaining": sorted(self.requirements["features"].keys() - self.accepted.keys())}
            self.report["status"] = previous
            return {"status": "FAILED", "delivery": delivery}
        if action == "focus":
            self.work.update({"feature": request["feature"]}, self.requirements["features"], self.accepted)
            return {"status": "FOCUSED", "working_memory": self.work.snapshot()}
        if action == "remember":
            if "work" not in request:
                raise ValueError("remember requires work metadata")
            return {"status": "RECORDED", "working_memory": self.work.snapshot()}
        if action == "read":
            if "path" in request and "paths" in request:
                raise ValueError("Supply path or paths, not both")
            paths = [request["path"]] if "path" in request else request["paths"]
            return self.repository.read(paths, start_line=request.get("start_line", 1),
                end_line=request.get("end_line"), start_column=request.get("start_column", 0))
        if action == "search":
            return self.repository.search(request["text"], path=request.get("path"),
                context_lines=request.get("context_lines", 3), offset=request.get("offset", 0))
        if action in {"edit", "replace"}:
            changed = self.repository.edit(request["edits"]) if action == "edit" else self.repository.replace(
                request["path"], request["old_text"], request["new_text"], request["sha256"])
            self.report["checks"] = None
            if any(path.endswith("package.json") or path == "package-lock.json" for path in changed):
                self.checks.installed = False
            return {"changed": changed, "revision": self.repository.revision}
        if action == "reference":
            relative = request["path"]
            if relative not in self.requirements["references"]:
                raise ValueError("Choose a reference path listed in the input requirements")
            cache_path = self.arc_dir / "visual_analysis.json"
            cache = json.loads(cache_path.read_text()) if cache_path.exists() else {}
            if relative not in cache:
                cache[relative] = VisualModel().analyze(self.input / relative, max_attempts=2)
                save_json(cache_path, cache)
            return cache[relative]
        if action == "check":
            force = request.get("force", False)
            if type(force) is not bool:
                raise ValueError("force must be a boolean")
            result = self.checks.run(request.get("kind", "all"), force=force) if isinstance(self.checks, Checks) else self.checks.run(request.get("kind", "all"))
            self.report["checks"] = result
            if result.get("scope") == "all":
                self.report["last_full_check"] = result
            return result
        if action == "browser":
            return self.checks.inspect(request.get("path", "/"), request.get("actions", []))
        if action == "restore":
            identity = request["checkpoint"]
            if identity not in self.report["checkpoints"]:
                raise ValueError("Choose a checkpoint returned by this run")
            self.accepted = self.repository.restore(identity)
            self.work.invalidate()
            self.report["checks"] = None
            self.checks.installed = False
            return {"restored": identity, "accepted": self.accepted}
        if action in {"accept", "finish"}:
            return self.accept(request, finish=action == "finish")
        raise ValueError(f"Unknown repository action: {action!r}")

    def accept(self, request, *, finish):
        features = {} if finish else request["features"]
        if not isinstance(features, dict) or (not finish and not features):
            raise ValueError("accept requires a nonempty map of scenario IDs to test paths")
        for identity, tests in features.items():
            if identity not in self.requirements["features"] or identity in self.accepted:
                raise ValueError(f"Unknown or already accepted feature: {identity}")
            if not isinstance(tests, list) or not tests:
                raise ValueError(f"Supply browser acceptance specs for {identity}")
            for path in tests:
                self.repository.path(path)
                if path not in self.checks.suites()["e2e"]:
                    raise ValueError(f"Missing browser acceptance spec: {path}")
        if finish and self.accepted.keys() != self.requirements["features"].keys():
            return {"status": "INCOMPLETE", "remaining": sorted(self.requirements["features"].keys() - self.accepted.keys())}
        for path, checksum in self.repository.frozen.items():
            if sha256(self.repository.path(path).read_bytes()).hexdigest() != checksum:
                raise ValueError(f"Previously accepted test changed: {path}")
        if finish:
            result = self.checks.run("all", force=True) if isinstance(self.checks, Checks) else self.checks.run("all")
        elif hasattr(self.checks, "verify"):
            result = self.checks.verify([path for tests in features.values() for path in tests], self.accepted)
        else:
            result = self.checks.run("all")
        self.report["checks"] = result
        if result.get("scope") == "all":
            self.report["last_full_check"] = result
        if result["status"] != "GREEN":
            return result
        audited = set(self.requirements["features"]) if finish else set(features)

"""Cross-layer source edits and immutable checkpoints in one generated repository."""

from bisect import bisect_right
from hashlib import sha256
import json
from pathlib import Path, PurePosixPath

from infrastructure.utils.files import save_bytes, save_json, save_text


EXCLUDED = {".arc", ".git", ".venv", "node_modules", "dist", "build", "coverage", "test-results", "__pycache__", "data"}
SUFFIXES = {".ts", ".tsx", ".js", ".jsx", ".mjs", ".css", ".html", ".json", ".sql", ".md", ".sh"}
# Executable test infrastructure stays trusted. Application wiring, routes and schema are editable.
HARNESS = {"deploy.sh", "frontend/playwright.e2e.config.ts", "frontend/vite.e2e.config.ts",
    "frontend/scripts/test-e2e.mjs", "frontend/tests/e2e/support/context.ts",
    "backend/tests/support/context.ts", "backend/scripts/copy-db.mjs", "backend/scripts/test-api.mjs"}

# Leave room for metadata inside the controller's 30,000-character observation window.
CONTENT_BUDGET = 18_000
MAX_SOURCE_BYTES = 2_000_000


def encoded_size(value):
    return len(json.dumps(value, ensure_ascii=False))


def line_starts(text):
    starts = [0]
    starts.extend(index + 1 for index, char in enumerate(text) if char == "\n" and index + 1 < len(text))
    return starts


def position(starts, offset):
    index = bisect_right(starts, offset) - 1
    return {"start_line": index + 1, "start_column": offset - starts[index]}


def bounded_end(text, start, stop, budget):
    """Bound escaped JSON content, including unusually long single source lines."""
    low, high = start, stop
    while low < high:
        middle = (low + high + 1) // 2
        if encoded_size(text[start:middle]) <= budget:
            low = middle
        else:
            high = middle - 1
    return low


class Repository:
    def __init__(self, output: Path):
        self.output = output.resolve()
        self.observed = {}
        self.frozen = {}
        self.revision = 0
        self.reading = {}
        self.changes = []

    def path(self, relative: str) -> Path:
        if not isinstance(relative, str) or not relative or "\\" in relative:
            raise ValueError("Use a canonical repository-relative POSIX file path")
        path = PurePosixPath(relative)
        if path.is_absolute() or str(path) != relative or ".." in path.parts:
            raise ValueError(f"Path escapes repository or is noncanonical: {relative}")
        if any(part.startswith(".") or part in EXCLUDED for part in path.parts) or path.suffix not in SUFFIXES:
            raise ValueError(f"Not a source file: {relative}")
        target = self.output
        for part in path.parts:
            target = target / part
            if target.is_symlink():
                raise ValueError(f"Symlinks are not source files: {relative}")
        if not target.resolve().is_relative_to(self.output) or target.is_dir():
            raise ValueError(f"Not a source file: {relative}")
        return target

    def paths(self) -> list[str]:
        result = []
        # Prune generated/dependency directories before descending into the tree.
        import os
        for directory, folders, filenames in os.walk(self.output, followlinks=False):
            folders[:] = sorted(folder for folder in folders if not folder.startswith(".")
                and folder not in EXCLUDED and not (Path(directory) / folder).is_symlink())
            for name in sorted(filenames):
                path = Path(directory) / name
                if not name.startswith(".") and not path.is_symlink() and path.suffix in SUFFIXES:
                    result.append(path.relative_to(self.output).as_posix())
        return sorted(result)

    def _source(self, relative):
        path = self.path(relative)
        if not path.is_file():
            return None, None
        if path.stat().st_size > MAX_SOURCE_BYTES:
            raise ValueError(f"Source exceeds 2 MB tool limit: {relative}; split the source file")
        content = path.read_bytes()
        return content.decode("utf-8-sig"), sha256(content).hexdigest()

    def _remember(self, relative, text, checksum, start, end, *, count_read=True):
        record = self.reading.get(relative)
        if record is None or record["sha256"] != checksum or self.observed.get(relative) != checksum:
            record = {"sha256": checksum, "spans": [], "repeats": {},
                "starts": line_starts(text), "size": len(text), "total_lines": len(line_starts(text)) if text else 0}
        spans = sorted(record["spans"] + [(start, end)])
        merged = []
        for left, right in spans:
            if merged and left <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(right, merged[-1][1]))
            else:
                merged.append((left, right))
        record["spans"] = merged
        key = (start, end)
        record["repeats"][key] = record["repeats"].get(key, 0) + int(count_read)
        self.reading.pop(relative, None)
        self.reading[relative] = record
        self.observed[relative] = checksum
        return record["repeats"][key]

    def _page(self, relative, text, checksum, start, stop, budget, *, count_read=True):
        end = bounded_end(text, start, stop, budget)
        starts = line_starts(text)
        begin, finish = position(starts, start), position(starts, end)
        repeats = self._remember(relative, text, checksum, start, end, count_read=count_read)
        result = {"sha256": checksum, "content": text[start:end],
            "writable": relative not in HARNESS and relative not in self.frozen,
            "total_lines": len(starts) if text else 0, **begin,
            "end_line": finish["start_line"], "end_column": finish["start_column"],
            "has_more": end < len(text), "full_file": start == 0 and end == len(text),
            "next_read": {"action": "read", "path": relative, **finish} if end < len(text) else None,
            "repeat_count": repeats}
        if repeats > 1:
            record = self.reading[relative]
            unread = self._unread(record)
            hint = f"Read the next unread range at {unread}." if unread else "Use replace, run a check, or investigate a new hypothesis."
            result["warning"] = "This exact range is unchanged since its previous read. " + hint
        return result

    @staticmethod
    def _unread(record):
        offset = 0
        for left, right in record["spans"]:
            if left > offset:
                break
            offset = max(offset, right)
        return position(record["starts"], offset) if offset < record["size"] else None

    def read(self, paths: list[str], *, start_line=1, end_line=None, start_column=0) -> dict:
        if not isinstance(paths, list) or not 1 <= len(paths) <= 12:
            raise ValueError("Read 1 to 12 files at a time")
        if len(set(paths)) != len(paths):
            raise ValueError("Read each path once per action")
        if type(start_line) is not int or start_line < 1 or type(start_column) is not int or start_column < 0:
            raise ValueError("start_line is 1-based and start_column is a nonnegative character offset")
        if end_line is None:
            end_line = start_line + 199
        if type(end_line) is not int or not start_line <= end_line < start_line + 500:
            raise ValueError("Read 1 to 500 lines per page; end_line must be >= start_line")
        result = {}
        for relative in paths:
            text, checksum = self._source(relative)
            if text is None:
                result[relative] = {"sha256": None, "content": None, "total_lines": 0,
                    "full_file": True, "has_more": False, "next_read": None,
                    "writable": relative not in HARNESS and relative not in self.frozen}
                continue
            starts = line_starts(text)
            if start_line > len(starts):
                raise ValueError(f"{relative} has {len(starts) if text else 0} lines; choose an existing line")
            left = starts[start_line - 1]
            line_end = starts[start_line] if start_line < len(starts) else len(text)
            if start_column > line_end - left or (start_column and start_column == line_end - left):
                raise ValueError(f"start_column is outside line {start_line}: {relative}")
            stop = starts[end_line] if end_line < len(starts) else len(text)
            result[relative] = self._page(relative, text, checksum, left + start_column, stop, CONTENT_BUDGET // len(paths))
        return result

    def search(self, text: str, *, path=None, context_lines=3, offset=0) -> dict:
        if not isinstance(text, str) or not text:
            raise ValueError("Search requires a nonempty literal string")
        if type(context_lines) is not int or not 0 <= context_lines <= 40:
            raise ValueError("context_lines must be between 0 and 40")
        if type(offset) is not int or offset < 0:
            raise ValueError("offset must be a nonnegative match index")
        hits = []
        seen = 0
        paths = [path] if path is not None else self.paths()
        for relative in paths:
            if self.path(relative).is_file() and self.path(relative).stat().st_size > MAX_SOURCE_BYTES:
                continue
            source, checksum = self._source(relative)
            if source is None:
                continue
            starts = line_starts(source)
            for index, left_edge in enumerate(starts):
                number = index + 1
                line = source[left_edge:starts[index + 1] if index + 1 < len(starts) else len(source)]
                if text in line:
                    seen += 1
                    if seen <= offset:
                        continue
                    if len(hits) == 10:
                        return {"matches": hits, "has_more": True, "next_search": {"action": "search",
                            "text": text, "path": path, "context_lines": context_lines, "offset": offset + len(hits)}}
                    match = starts[number - 1] + line.index(text)
                    # Keep the match in view even when preceding context or the matching line is huge.
                    left = max(starts[max(0, number - 1 - context_lines)], match - 200)
                    last = number + context_lines
                    stop = starts[last] if last < len(starts) else len(source)
                    snippet = self._page(relative, source, checksum, left, stop, 1_200)
                    preview_end = bounded_end(line, 0, min(500, len(line)), 500)
                    hits.append({"path": relative, "line": number, "text": line[:preview_end], "context": snippet})
        return {"matches": hits, "has_more": False, "next_search": None}

    def memory(self):
        """Keep source-version/range receipts after individual observations leave model context."""
        files = {}
        for relative, record in list(self.reading.items())[-60:]:
            _, current = self._source(relative)
            stale = current != record["sha256"] or self.observed.get(relative) != current
            files[relative] = {"sha256": current, "read_sha256": record["sha256"], "stale": stale,
                "total_lines": record["total_lines"],
                "read_ranges": [{**position(record["starts"], left),
                    "end_line": position(record["starts"], right)["start_line"],
                    "end_column": position(record["starts"], right)["start_column"]}
                    for left, right in record["spans"][:12]],
                "fully_read": not stale and self._unread(record) is None,
                "next_read": {"action": "read", "path": relative, **(position([0], 0) if stale else self._unread(record))}
                    if stale or self._unread(record) else None}
        return {"files": files, "recent_changes": self.changes[-12:]}

    def replace(self, relative, old_text, new_text, checksum):
        if not isinstance(old_text, str) or not old_text or not isinstance(new_text, str):
            raise ValueError("replace requires nonempty old_text and string new_text")
        content, current = self._source(relative)
        if content is None or checksum != current or self.observed.get(relative) != current:
            raise ValueError(f"Read or search the current file and supply its sha256 before replace: {relative}")
        count = content.count(old_text)
        if count == 1 and content.find(old_text, content.find(old_text) + 1) >= 0:
            count = 2  # Overlapping matches such as "aa" within "aaa" are also ambiguous.
        if count != 1:
            raise ValueError(f"old_text must match exactly once, found {count}: {relative}; search and include more surrounding code")
        return self._publish([{"path": relative, "sha256": checksum,
            "content": content.replace(old_text, new_text, 1)}], require_complete=False)

    def edit(self, edits: list[dict]) -> list[str]:
        return self._publish(edits, require_complete=True)

    def _publish(self, edits, *, require_complete):
        if not isinstance(edits, list) or not 1 <= len(edits) <= 30:
            raise ValueError("Supply 1 to 30 complete file edits")
        staged, originals = {}, {}
        for edit in edits:
            relative, content = edit["path"], edit["content"]
            target = self.path(relative)
            if relative in HARNESS or relative in self.frozen:
                raise ValueError(f"Frozen acceptance test or execution harness: {relative}")
            if relative in staged:
                raise ValueError(f"Duplicate edit: {relative}")
            if content is not None and (not isinstance(content, str) or len(content.encode()) > 200_000):
                raise ValueError("File content must be UTF-8 text under 200 KiB, or null for deletion")
            previous = target.read_bytes() if target.is_file() else None
